{
  "description": "The creature is shown in right-facing lateral view, standing low to the ground on four short limbs. It has a stout, elongated body with a blunt, rounded pale pink head at the anterior end and a thick tail extending out of the frame to the left at the posterior end. The dorsal surface from just behind the head to the tail is covered in overlapping large dark brown scales, while the ventral torso, sides of the body, head, and limbs are covered in wrinkled, hairless, pale pink skin with prominent transverse folds. Behind the head on both sides are multiple feathery pinkish-red external gills. The limbs are thick and columnar, ending in broad five-toed feet with small claws. The overall appearance is smooth and moist on the head and wrinkled on the body, with large dark eyes on the sides of the head.",
  "parts": [
    {
      "part": "head",
      "looks_like": "pale pink, smooth and slightly glossy, rounded and blunt-snouted with a small nostril at the tip, a slightly upturned mouth line, and large round eyes; located at the anterior end facing right"
    ,
      "where": "anterior end, in front of the gills and scaled back"
    },
    {
      "part": "eyes",
      "looks_like": "large, round, glossy with a large dark pupil and a pale blue-grey iris and a small highlight; lateral placement on the head",
      "where": "on the sides of the head, one clearly visible on the near side"
    },
    {
      "part": "gills",
      "looks_like": "feathery, branching external gills, pinkish-red with a central stalk and many fine filaments along the sides; 4 stalks visible on the near side and 3 to 4 stalks visible on the far side behind the head",
      "where": "protruding laterally from the neck region immediately behind the head, on both left and right sides"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, teardrop-shaped keratinous scales, dark brown in the center with lighter tan-brown edges and fine radial lines, arranged in diagonal overlapping rows like roof tiles",
      "where": "covering the entire dorsal surface from the base of the gills over the arched back to the base of the tail"
    },
    {
      "part": "plates",
      "looks_like": "same as scales - large overlapping armored plates/scales as described above",
      "where": "dorsal back and tail base"
    },
    {
      "part": "skin/markings",
      "looks_like": "wrinkled, hairless, pale pink skin with deep transverse folds and wrinkles on the torso and limbs; subtle mottled grey shading on the top of the head; no distinct spots, stripes or feathers",
      "where": "on the head, ventral torso, sides, and all four limbs"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, stout columnar limbs with deeply wrinkled pale pink skin, muscular with folded skin at the joints",
      "where": "two forelimbs under the chest and two hindlimbs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, splayed, five-toed with short blunt light tan claws on each digit, wrinkled pink skin continuing onto the toes",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, tapering, dorsal side covered in the same dark brown overlapping scales as the back, ventral side wrinkled pale pink skin; only the base and proximal portion is visible",
      "where": "at the posterior end, extending to the left and cropped by the edge of the image"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin", "naked mole-rat"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
